styles.css:
position: relative;
overflow: hidden;
--ls-card-category-border-active: var(--wp--custom--color--link--accent);
--ls-card-category-shadow-active: var(--wp--custom--shadow--card--hover);
--ls-card-category-lift: var(--wp--custom--animation--lift--md);

& .ls-card-category__content {
	flex: 1 1 auto;
	display: flex;
	flex-direction: column;
	gap: var(--wp--preset--spacing--10);
}
